import{_ as l,W as o,s as d,u as r,ah as n,I as p,w as a,Z as t,A as i}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const f=JSON.parse('{"title":"什么是 Git 遴选（cherry-pick）？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是 Git 遴选（cherry-pick）？ | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"什么是 Git 遴选（cherry-pick）？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是 Git 遴选（cherry-pick）？ | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210407 What is Git cherry-picking","title":"什么是 Git 遴选（cherry-pick）？","tag":"202104"},"relativePath":"202104/20210407 What is Git cherry-picking.md","filePath":"[post].md"}'),c={name:"202104/20210407 What is Git cherry-picking.md"};function g(h,s,u,b,k,m){const e=o("Link");return r(),d("div",null,[s[25]||(s[25]=n('<h1 id="什么是-git-遴选-cherry-pick" tabindex="-1">什么是 Git 遴选（cherry-pick）？ <a class="header-anchor" href="#什么是-git-遴选-cherry-pick" aria-label="Permalink to 什么是 Git 遴选（cherry-pick）？">​</a></h1><blockquote><p>了解 <code>git cherry-pick</code> 命令是什么，为什么用以及如何使用。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/14/131735o63v3ow6y2wc281o.jpg" alt=""></p><p>当你和一群程序员一起工作时，无论项目大小，处理多个 Git 分支之间的变更都会变得很困难。有时，你不想将整个 Git 分支合并到另一个分支，而是想选择并移动几个特定的提交。这个过程被称为 “<ruby>遴选<rt>cherry-pick</rt></ruby>”。</p><p>本文将介绍“遴选”是什么、为何使用以及如何使用。</p><p>那么让我们开始吧。</p><h3 id="什么是遴选" tabindex="-1">什么是遴选？ <a class="header-anchor" href="#什么是遴选" aria-label="Permalink to 什么是遴选？">​</a></h3>',7)),p("p",null,[s[1]||(s[1]=a("使用遴选（")),s[2]||(s[2]=p("code",null,"cherry-pick",-1)),s[3]||(s[3]=a("）命令，Git 可以让你将任何分支中的个别提交合并到你当前的 ")),t(e,{href:"https://acompiler.com/git-head/"},{default:i(()=>s[0]||(s[0]=[a("Git HEAD")])),_:1}),s[4]||(s[4]=a(" 分支中。"))]),s[26]||(s[26]=n('<p>当执行 <code>git merge</code> 或者 <code>git rebase</code> 时，一个分支的所有提交都会被合并。<code>cherry-pick</code> 命令允许你选择单个提交进行整合。</p><h3 id="遴选的好处" tabindex="-1">遴选的好处 <a class="header-anchor" href="#遴选的好处" aria-label="Permalink to 遴选的好处">​</a></h3><p>下面的情况可能会让你更容易理解遴选功能。</p><p>想象一下，你正在为即将到来的每周冲刺实现新功能。当你的代码准备好了，你会把它推送到远程分支，准备进行测试。</p><p>然而，客户并不是对所有修改都满意，要求你只呈现某些修改。因为客户还没有批准下次发布的所有修改，所以 <code>git rebase</code> 不会有预期的结果。为什么会这样？因为 <code>git rebase</code> 或者 <code>git merge</code> 会把上一个冲刺的每一个调整都纳入其中。</p><p>遴选就是答案！因为它只关注在提交中添加的变更，所以遴选只会带入批准的变更，而不添加其他的提交。</p><p>还有其他几个原因可以使用遴选：</p><ul><li>这对于 bug 修复是必不可少的，因为 bug 是出现在开发分支中对应的提交的。</li><li>你可以通过使用 <code>git cherry-pick</code> 来避免不必要的工作，而不用使用其他选项例如 <code>git diff</code> 来应用特定变更。</li><li>如果因为不同 Git 分支的版本不兼容而无法将整个分支联合起来，那么它是一个很有用的工具。</li></ul><h3 id="使用-cherry-pick-命令" tabindex="-1">使用 cherry-pick 命令 <a class="header-anchor" href="#使用-cherry-pick-命令" aria-label="Permalink to 使用 cherry-pick 命令">​</a></h3>',9)),p("p",null,[s[6]||(s[6]=a("在 ")),s[7]||(s[7]=p("code",null,"cherry-pick",-1)),s[8]||(s[8]=a(" 命令的最简单形式中，你只需使用 ")),t(e,{href:"https://en.wikipedia.org/wiki/Secure_Hash_Algorithms"},{default:i(()=>s[5]||(s[5]=[a("SHA")])),_:1}),s[9]||(s[9]=a(" 标识符来表示你想整合到当前 HEAD 分支的提交。"))]),s[27]||(s[27]=n(`<p>要获得提交的哈希值，可以使用 <code>git log</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log --oneline</span></span></code></pre></div><p>当你知道了提交的哈希值后，你就可以使用 <code>cherry-pick</code> 命令。</p><p>语法是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git cherry-pick &lt;commit sha&gt;</span></span></code></pre></div><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git cherry-pick 65be1e5</span></span></code></pre></div><p>这将会把指定的修改合并到当前已签出的分支上。</p><p>如果你想做进一步的修改，也可以让 Git 将提交的变更内容添加到你的工作副本中。</p><p>语法是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git cherry-pick &lt;commit sha&gt; --no-commit</span></span></code></pre></div><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git cherry-pick 65be1e5 --no-commit</span></span></code></pre></div><p>如果你想同时选择多个提交，请将它们的提交哈希值用空格隔开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git cherry-pick hash1 hash3</span></span></code></pre></div><p>当遴选提交时，你不能使用 <code>git pull</code> 命令，因为它能获取一个仓库的提交<strong>并</strong>自动合并到另一个仓库。<code>cherry-pick</code> 是一个专门不这么做的工具；另一方面，你可以使用 <code>git fetch</code>，它可以获取提交，但不应用它们。毫无疑问，<code>git pull</code> 很方便，但它不精确。</p><h3 id="自己尝试" tabindex="-1">自己尝试 <a class="header-anchor" href="#自己尝试" aria-label="Permalink to 自己尝试">​</a></h3><p>要尝试这个过程，启动终端并生成一个示例项目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkdir fruit.git</span></span>
<span class="line"><span>$ cd fruit.git</span></span>
<span class="line"><span>$ git init .</span></span></code></pre></div><p>创建一些数据并提交：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;Kiwifruit&quot; &gt; fruit.txt</span></span>
<span class="line"><span>$ git add fruit.txt</span></span>
<span class="line"><span>$ git commit -m &#39;First commit&#39;</span></span></code></pre></div><p>现在，通过创建一个项目的复刻来代表一个远程开发者：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkdir ~/fruit.fork</span></span>
<span class="line"><span>$ cd !$</span></span>
<span class="line"><span>$ echo &quot;Strawberry&quot; &gt;&gt; fruit.txt</span></span>
<span class="line"><span>$ git add fruit.txt</span></span>
<span class="line"><span>$ git commit -m &#39;Added a fruit&quot;</span></span></code></pre></div><p>这是一个有效的提交。现在，创建一个不好的提交，代表你不想合并到你的项目中的东西：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;Rhubarb&quot; &gt;&gt; fruit.txt</span></span>
<span class="line"><span>$ git add fruit.txt</span></span>
<span class="line"><span>$ git commit -m &#39;Added a vegetable that tastes like a fruit&quot;</span></span></code></pre></div><p>返回你的仓库，从你的假想的开发者那里获取提交的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cd ~/fruit.git</span></span>
<span class="line"><span>$ git remote add dev ~/fruit.fork</span></span>
<span class="line"><span>$ git fetch dev</span></span>
<span class="line"><span>remote: Counting objects: 6, done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (2/2), done.</span></span>
<span class="line"><span>remote: Total 6 (delta 0), reused 0 (delta 0)</span></span>
<span class="line"><span>Unpacking objects: 100% (6/6), done...</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log –oneline dev/master</span></span>
<span class="line"><span>e858ab2 Added a vegetable that tastes like a fruit</span></span>
<span class="line"><span>0664292 Added a fruit</span></span>
<span class="line"><span>b56e0f8 First commit</span></span></code></pre></div><p>你已经从你想象中的开发者那里获取了提交的内容，但你还没有将它们合并到你的版本库中。你想接受第二个提交，但不想接受第三个提交，所以使用 <code>cherry-pick</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git cherry-pick 0664292</span></span></code></pre></div><p>第二次提交现在在你的仓库里了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat fruit.txt</span></span>
<span class="line"><span>Kiwifruit</span></span>
<span class="line"><span>Strawberry</span></span></code></pre></div><p>将你的更改推送到远程服务器上，这就完成了！</p><h3 id="避免使用遴选的原因" tabindex="-1">避免使用遴选的原因 <a class="header-anchor" href="#避免使用遴选的原因" aria-label="Permalink to 避免使用遴选的原因">​</a></h3><p>在开发者社区中，通常不鼓励所以遴选。主要原因是它会造成重复提交，而你也失去了跟踪你的提交历史的能力。</p><p>如果你不按顺序地遴选了大量的提交，这些提交会被记录在你的分支中，这可能会在 Git 分支中导致不理想的结果。</p><p>遴选是一个强大的命令，如果没有正确理解可能发生的情况，它可能会导致问题。不过，当你搞砸了，提交到错误的分支时，它可能会救你一命（至少是你当天的工作）。</p><hr>`,38)),p("p",null,[s[11]||(s[11]=a("via: ")),t(e,{href:"https://opensource.com/article/21/4/cherry-picking-git"},{default:i(()=>s[10]||(s[10]=[a("https://opensource.com/article/21/4/cherry-picking-git")])),_:1})]),p("p",null,[s[16]||(s[16]=a("作者：")),t(e,{href:"https://opensource.com/users/acompiler"},{default:i(()=>s[12]||(s[12]=[a("Rajeev Bera")])),_:1}),s[17]||(s[17]=a(" 选题：")),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>s[13]||(s[13]=[a("lujun9972")])),_:1}),s[18]||(s[18]=a(" 译者：")),t(e,{href:"https://github.com/geekpi"},{default:i(()=>s[14]||(s[14]=[a("geekpi")])),_:1}),s[19]||(s[19]=a(" 校对：")),t(e,{href:"https://github.com/wxy"},{default:i(()=>s[15]||(s[15]=[a("wxy")])),_:1})]),p("p",null,[s[22]||(s[22]=a("本文由 ")),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>s[20]||(s[20]=[a("LCTT")])),_:1}),s[23]||(s[23]=a(" 原创编译，")),t(e,{href:"https://linux.cn/"},{default:i(()=>s[21]||(s[21]=[a("Linux中国")])),_:1}),s[24]||(s[24]=a(" 荣誉推出"))])])}const C=l(c,[["render",g]]);export{f as __pageData,C as default};
